//! Shared window and tray artwork, generated by `scripts/build_icons.py`.
use eframe::egui::IconData;

pub fn app_icon() -> IconData {
    eframe::icon_data::from_png_bytes(include_bytes!("../assets/krot.png"))
        .expect("embedded application icon must be a valid PNG")
}

pub fn tray_icon(badge: Option<[u8; 4]>) -> IconData {
    let mut icon = eframe::icon_data::from_png_bytes(include_bytes!("../assets/krot-tray.png"))
        .expect("embedded tray icon must be a valid PNG");
    if let Some(color) = badge {
        // Whole pixels keep the status light distinct at small tray sizes.
        for y in 22..32 {
            for x in 22..32 {
                if (x == 22 || x == 31) && (y == 22 || y == 31) {
                    continue;
                }
                let pixel = if (24..30).contains(&x) && (24..30).contains(&y) {
                    color
                } else {
                    [16, 23, 26, 255]
                };
                let offset = ((y * icon.width + x) * 4) as usize;
                icon.rgba[offset..offset + 4].copy_from_slice(&pixel);
            }
        }
    }
    icon
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_icons_have_expected_sizes_and_transparent_backgrounds() {
        for (icon, size) in [(app_icon(), 256), (tray_icon(None), 32)] {
            assert_eq!((icon.width, icon.height), (size, size));
            assert_eq!(icon.rgba.len(), (size * size * 4) as usize);
            assert_eq!(&icon.rgba[..4], &[0, 0, 0, 0]);
            assert!(
                icon.rgba
                    .as_chunks::<4>()
                    .0
                    .iter()
                    .any(|pixel| pixel[3] == 255)
            );
        }
    }

    #[test]
    fn badge_preserves_color_alpha_and_the_rest_of_the_mole() {
        let original = tray_icon(None);
        let color = [172, 208, 148, 128];
        let badged = tray_icon(Some(color));
        let pixel = |icon: &IconData, x: usize, y: usize| {
            let offset = (y * icon.width as usize + x) * 4;
            <[u8; 4]>::try_from(&icon.rgba[offset..offset + 4]).unwrap()
        };
        assert_eq!(pixel(&badged, 26, 26), color);
        assert_eq!(pixel(&badged, 23, 26), [16, 23, 26, 255]);
        assert_eq!(pixel(&badged, 31, 31), pixel(&original, 31, 31));
        for y in 0..32 {
            for x in 0..32 {
                if x < 22 || y < 22 {
                    assert_eq!(pixel(&badged, x, y), pixel(&original, x, y));
                }
            }
        }
        assert_ne!(badged.rgba, original.rgba);
        assert_eq!(tray_icon(None).rgba, original.rgba);
    }
}
